// The logic of the web demo without a page around it: what a tile would send, how a usage is called, how the LED bars are lit.
// Everything here is a pure function of the keymap that the firmware is built from (keymap.js, generated by scripts/dump_keymap.sh),
// so it can be tested without a browser.

/**
 * One binding of the keymap: [HID page, usage id, modifier byte, usage name, label of the tile or null].
 * @typedef {[number, number, number, string, (string | null)]} Binding
 */

/**
 * A layer of the keymap.
 * @typedef {object} Layer
 * @property {string} title
 * @property {number} rows
 * @property {number} cols
 * @property {string} color the colour of the LED bar on this page, as #RRGGBB
 * @property {Binding[]} tiles
 */

/**
 * What a tile would send.
 * @typedef {object} Description
 * @property {string} text the key as text, for example Ctrl+Shift+B
 * @property {'keyboard' | 'consumer' | 'system' | 'mouse'} kind
 * @property {[number, number[]]} down the report id and the bytes of the press
 * @property {[number, number[]] | null} up the report id and the bytes of the release; null when there is no release (a held modifier)
 * @property {string} detail the numbers behind it, for the log
 * @property {string | null} label the caption of the tile
 * @property {boolean} [blocked] true for Power Down and Sleep: shown, never sent
 */

/** A rectangle on the 320 x 240 screen. @typedef {{index: number, x: number, y: number, w: number, h: number}} TileRect */

export const SCREEN_W = 320;
export const SCREEN_H = 240;
/** The grid of a key page: the same arithmetic as the page builder of the firmware (src/ui.cpp). */
export const GAP = 3;
export const BODY_H = 202;
/** The index of the Locks page: pages 0 to 25 are the key layers. */
export const LOCKS = 26;
/** The pages of the board: the 26 key layers, the Locks page and the three pages of the lamps (the Disk page, the lamp screen and the bar lamps). */
export const PAGES = 30;
/** The titles of the pages after the Locks page: pages 27 to 29. */
export const LAMP_PAGES = ['Disk', 'Lamp grid', 'Lamp bar'];
/** The same pages as the shell calls them in `state` (src/ui.cpp). */
export const LAMP_STATE_TITLES = ['Disk', 'Lamps-screen', 'Lamps-bar'];

/**
 * Whether a page is one of the three pages of the lamps, which have no screenshot: the screen is drawn from the state of the lamps.
 * @param {number} page
 * @returns {boolean}
 */
export function isLampPage(page) {
  return page > LOCKS;
}
export const LOCK_NAMES = ['Caps', 'Num', 'Scroll'];

const MODIFIERS = /** @type {const} */ ([[1, 'Ctrl'], [2, 'Shift'], [4, 'Alt'], [8, 'Win'], [16, 'RCtrl'], [32, 'RShift'], [64, 'RAlt'], [128, 'RWin']]);
const SYMBOLS = /** @type {Record<string, string>} */ ({
  BANG: '!', AT: '@', HASH: '#', DOLLAR: '$', PERCENT: '%', CARET: '^', AMPERSAND: '&', STAR: '*',
  LEFT_BRACKET: '(', RIGHT_BRACKET: ')', LESSTHAN: '<', GREATERTHAN: '>', UNDERSCORE: '_', PLUS: '+',
});
/** Names that the usual splitting at underscores does not make readable. @type {Record<string, string>} */
const SPOKEN = { PAGEUP: 'Page Up', PAGEDOWN: 'Page Down' };
const SYSTEM_POWER_DOWN = 0x81;
const SYSTEM_SLEEP = 0x82;

/**
 * A number as upper case hexadecimal with a minimum width.
 * @param {number} n
 * @param {number} width
 * @returns {string}
 */
export function hex(n, width) {
  return n.toString(16).toUpperCase().padStart(width, '0');
}

/**
 * The bytes of a report as hexadecimal pairs.
 * @param {number[]} list
 * @returns {string}
 */
export function bytes(list) {
  return list.map((b) => hex(b, 2)).join(' ');
}

/**
 * @param {string} s
 * @returns {string}
 */
function words(s) {
  if (s.length <= 3) return s;
  return s.toLowerCase().split('_').map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
}

/**
 * A usage name of the firmware's headers as text: KP_NUM_LOCK_AND_CLEAR is "Keypad Num Lock / Clear", ID_7_AND_AMPERSAND is "7 / &".
 * @param {string} name
 * @returns {string}
 */
export function pretty(name) {
  const spoken = SPOKEN[name];
  if (spoken) return spoken;
  let rest = name.replace(/^SYS_/u, '').replace(/^ID_/u, '');
  const keypad = rest.startsWith('KP_');
  if (keypad) rest = rest.slice(3);
  const [first, second] = rest.split('_AND_');
  let text = words(first ?? '');
  if (second !== undefined) text += ` / ${SYMBOLS[second] ?? words(second)}`;
  return keypad ? `Keypad ${text}` : text;
}

/**
 * The single modifiers of a modifier byte, for example Ctrl+Shift.
 * @param {number} mask
 * @returns {string}
 */
export function modParts(mask) {
  return MODIFIERS.filter(([bit]) => (mask & bit) !== 0).map(([, name]) => name).join('+');
}

/**
 * The modifier byte as a name: Meh (Ctrl+Shift+Alt) and Hyper (Ctrl+Shift+Alt+Win), on the left or on the right, otherwise the single modifiers.
 * @param {number} mask
 * @returns {string}
 */
export function modText(mask) {
  switch (mask) {
    case 0x0f: return 'Hyper';
    case 0x07: return 'Meh';
    case 0xf0: return 'RHyper';
    case 0x70: return 'RMeh';
    default: return modParts(mask);
  }
}

/**
 * What the device does for a binding: the report ids and bytes of src/HIDManager.cpp. Nothing here sends anything.
 * @param {Binding} binding
 * @returns {Description | null} null for a binding of a page that the device cannot send
 */
export function describe(binding) {
  const [page, id, mod, name, label] = binding;
  if (page === 7) {
    let modifiers = mod;
    let key = 0;
    if (id >= 0xe0 && id <= 0xe7) modifiers |= 1 << (id - 0xe0);
    else if (id <= 0xdd) key = id;
    const prefix = modText(mod);
    const expanded = modText(mod) === modParts(mod) ? '' : ` = ${modParts(mod)}`;
    return {
      text: (prefix ? `${prefix}+` : '') + pretty(name),
      kind: 'keyboard',
      down: [1, [modifiers, 0, key, 0, 0, 0, 0, 0]],
      up: [1, [0, 0, 0, 0, 0, 0, 0, 0]],
      detail: `modifiers 0x${hex(modifiers, 2)}${expanded}, key 0x${hex(key, 2)}`,
      label,
    };
  }
  if (page === 12) {
    return { text: pretty(name), kind: 'consumer', down: [2, [id & 255, id >> 8]], up: [2, [0, 0]], detail: `usage 0x${hex(id, 4)} (page 0x0C)`, label };
  }
  if (page === 1) {
    return {
      text: pretty(name), kind: 'system', down: [3, [1 << (id - 0x81)]], up: [3, [0]], detail: `usage 0x${hex(id, 2)} (page 0x01)`, label,
      blocked: id === SYSTEM_POWER_DOWN || id === SYSTEM_SLEEP,
    };
  }
  return null;
}

/**
 * The click areas of the non-empty tiles of a key page, from the grid arithmetic of the firmware.
 * @param {Layer} layer
 * @returns {TileRect[]}
 */
export function tileRects(layer) {
  const w = Math.floor((SCREEN_W - (layer.cols + 1) * GAP) / layer.cols);
  const h = Math.floor((BODY_H - (layer.rows + 1) * GAP) / layer.rows);
  /** @type {TileRect[]} */
  const rects = [];
  layer.tiles.forEach((tile, index) => {
    if (tile[0] === 0) return;     // an empty tile
    rects.push({ index, x: GAP + (index % layer.cols) * (w + GAP), y: GAP + Math.floor(index / layer.cols) * (h + GAP), w, h });
  });
  return rects;
}

/**
 * A colour as #RRGGBB to three numbers.
 * @param {string} color
 * @returns {number[]}
 */
export function parseColor(color) {
  return [1, 3, 5].map((i) => parseInt(color.slice(i, i + 2), 16));
}

/**
 * The ten LEDs of the M5GO base as the firmware lights them: the colour of the layer on a key page; on the Locks page one active lock fills its
 * own two LEDs (lamps 0 and 1 for Caps, 2 and 3 for Num, 4 and 5 for Scroll), several active locks add up over the whole bar, and with none the bar is dark.
 * @param {number} page
 * @param {number} mask the locks that are on: Caps 1, Num 2, Scroll 4
 * @param {string} layerColor the colour of the layer, as #RRGGBB
 * @param {number[][]} lockColors the colours of the locks
 * @returns {number[][]} ten colours, one per lamp
 */
export function barColours(page, mask, layerColor, lockColors) {
  if (page < LOCKS) return Array.from({ length: 10 }, () => parseColor(layerColor));
  if (page > LOCKS) return Array.from({ length: 10 }, () => [0, 0, 0]);          // the pages of the lamps: the PC has the lamps, the board shows none of its own
  const active = [0, 1, 2].filter((k) => (mask & (1 << k)) !== 0);
  const dark = () => [0, 0, 0];
  const out = Array.from({ length: 10 }, dark);
  if (active.length > 1) {
    const mix = [0, 1, 2].map((c) => Math.min(255, active.reduce((sum, k) => sum + (lockColors[k]?.[c] ?? 0), 0)));
    return out.map(() => mix);
  }
  const [only] = active;
  if (only !== undefined) {
    for (let i = Math.floor(only * 10 / 5); i < Math.floor((only + 1) * 10 / 5); i++) out[i] = lockColors[only] ?? dark();
  }
  return out;
}

/**
 * The screenshot of a page: one per key layer and eight of the Locks page, one per state of the locks.
 * @param {number} page
 * @param {number} mask the locks that are on: Caps 1, Num 2, Scroll 4
 * @returns {string}
 */
export function pageImage(page, mask) {
  if (page < LOCKS) return `img/lvgl/s3-${String(page).padStart(2, '0')}.png`;
  if (page > LOCKS) return '';                                                    // no screenshot: the screen is drawn from the lamps
  return `img/lvgl/s3-26-${mask & 1 ? 1 : 0}${mask & 2 ? 1 : 0}${mask & 4 ? 1 : 0}.png`;
}

/**
 * The state of the locks as text for the status line.
 * @param {number} mask
 * @returns {string}
 */
export function lockText(mask) {
  return LOCK_NAMES.map((name, k) => `${name} ${mask & (1 << k) ? 'on' : 'off'}`).join(', ');
}
